      initial={{ opacity: 0, y: -50 }}
      animate={{ opacity: 1, y: 0 }}
      transition={{ duration: 1 }}
    >Muhammed Fazal
    <motion.p
      className="relative mt-3 text-lg md:text-xl text-gray-600 dark:text-gray-400 z-10"
      initial={{ opacity: 0, y: -20 }}
      animate={{ opacity: 1, y: 0 }}
      transition={{ delay: 0.2, duration: 0.8 }}
      >Software Engineer · Full-Stack Developer · Application Support Engineer · Data Engineer
    </motion.p>
    </motion.h1>
    <motion.p
      className="relative text-xl md:text-2xl mb-6 max-w-2xl z-10 text-gray-700 dark:text-gray-300"
      initial={{ opacity: 0, y: 50 }}
      animate={{ opacity: 1, y: 0 }}
      transition={{ delay: 0.5, duration: 1 }}
    >
      Backend-focused Full Stack Developer with 6+ years building scalable backend systems and cross-platform applications.
    </motion.p>
    <motion.a
      href="#contact"
      className="relative px-6 py-3 bg-primary text-white font-semibold rounded-lg hover:bg-accent transition z-10"
      initial={{ opacity: 0, scale: 0.8 }}
      animate={{ opacity: 1, scale: 1 }}
      transition={{ delay: 1, duration: 0.5 }}
    >
      Contact Me
    </motion.a>
  </section>
);

// About Section
const About = () => (
  <section id="about" className="relative bg-bgLight dark:bg-bgDark">
    <Particles />
    <SectionContainer>
      <h2 className="text-4xl font-bold text-primary dark:text-accent mb-6 text-center">About Me</h2>
      <p className="text-gray-700 dark:text-gray-300 mb-4 text-lg leading-relaxed">
        Backend-focused Full Stack Developer with 6+ years developing scalable backend systems and cross-platform applications using Laravel, PHP, Vue.js, Node, Python, TypeScript, JavaScript, React, and React Native.
      </p>
      <p className="text-gray-700 dark:text-gray-300 mb-4 text-lg leading-relaxed">
        Skilled in designing and developing scalable web applications, APIs, and database-driven solutions, with expertise in both frontend and backend development, API integration, and performance optimization. Experienced in Agile/Scrum environments, delivering high-quality projects on schedule. Proficient in technical support, troubleshooting, and end-user training, with strong problem-solving, communication, and collaboration skills. Quick to adapt to new technologies and committed to implementing efficient, innovative solutions.
      </p>
      <p className="text-gray-700 dark:text-gray-300 mb-4 text-lg leading-relaxed">
        Specialized in backend architecture, microservices, secure REST APIs, queue workers, performance optimization, and cloud deployments. Experienced building enterprise-level platforms including ERP, WMS, and inventory systems with AWS, GCP, Azure, Redis, Horizon, SQS, and MySQL.
      </p>
      <p className="text-gray-700 dark:text-gray-300 mb-4 text-lg leading-relaxed">
        🏠Sweden | 📞+46 764502891 | 📩muhammedfazalkv@gmail.com | 🟦<a href="https://www.linkedin.com/in/muhammed-fazal-kv
" className="text-primary dark:text-accent hover:underline">LinkedIn</a> | 💼Swedish Residence & Work Permit | Immediate Joiner
      </p>
    </SectionContainer>
  </section>
);


